const connetor_plugin=(()=>{class OperacionTicket{constructor(a,d){this.accion=a+"",this.datos=d+""}}class ConectorPlugin{static URL_PLUGIN_POR_DEFECTO="http://localhost:4567";static AccionText="AccionText";static Accionqr="qr";static AccionFontsize="fontsize";static AccionTextaling="textaling";static AccionFeed="feed";static AccionBarcode_ean13="barcode_ean13";static AccionBarcode_code39="barcode_39";static AccionBarcode_code128="barcode_128";static AccionImg_location="img_url";static AccionCut="cut";static AccionPDF="pdf";constructor(r=ConectorPlugin.URL_PLUGIN_POR_DEFECTO){this.ruta=r,this.operaciones=[]}static obtenerImpresoras(u){if(u)ConectorPlugin.URL_PLUGIN_POR_DEFECTO=u;return fetch(ConectorPlugin.URL_PLUGIN_POR_DEFECTO+"/getprinters").then(r=>r.json())}addText(t){this.operaciones.push(new OperacionTicket(ConectorPlugin.AccionText,t));return this}addQR(q){this.operaciones.push(new OperacionTicket(ConectorPlugin.Accionqr,q));return this}setFontSize(s){this.operaciones.push(new OperacionTicket(ConectorPlugin.AccionFontsize,s));return this}async printPDF(b,p,a){const d={operaciones:[new OperacionTicket(ConectorPlugin.AccionPDF,b)],nombre_impresora:p,api_key:a};const r=await fetch(this.ruta+"/imprimir",{method:"POST",body:JSON.stringify(d)});return await r.json()}}return ConectorPlugin})();
